             if grid[r][c] != bg and 0 < r < h-1 and 0 < c < w-1]
    ink = grid[marks[0][0]][marks[0][1]] if marks else 1
    # Each perimeter run emits parallel rays from positions one cell in, then
    # every two cells along the run; rays cross the interior and mark hits as 4.
    for col in (0, w-1):
        r = 0
        while r < h:
            if grid[r][col] == bg:
                r += 1
                continue
            color, start = grid[r][col], r
            while r < h and grid[r][col] == color:
                r += 1
            for rr in range(start+1, r, 2):
                for c in range(1, w-1):
                    if grid[rr][c] == bg:
                        out[rr][c] = ink
                    elif grid[rr][c] != color:
                        out[rr][c] = 4
    for row in (0, h-1):
        c = 0
        while c < w:
            if grid[row][c] == bg:
                c += 1
                continue
            color, start = grid[row][c], c
            while c < w and grid[row][c] == color:
                c += 1
            for cc in range(start+1, c, 2):
                for r in range(1, h-1):
                    if grid[r][cc] == bg:
                        out[r][cc] = ink
                    elif grid[r][cc] != color:
                        out[r][cc] = 4
    return out
