def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {v: sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}
    bg = max(counts, key=counts.get)
    # Each isolated point casts a straight ray toward the nearest aligned
    # non-background border/object; the source becomes 4.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or r in (0, h-1) or c in (0, w-1):
                continue
            choices = []
            for dr, dc in ((0,-1),(0,1),(-1,0),(1,0)):
                rr, cc = r+dr, c+dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    rr += dr; cc += dc
                if 0 <= rr < h and 0 <= cc < w:
                    choices.append((abs(rr-r)+abs(cc-c), dr, dc, rr, cc))
            if choices:
                _, dr, dc, rr, cc = min(choices)
                i, j = r+dr, c+dc
                while (i,j) != (rr,cc):
                    out[i][j] = color
                    i += dr; j += dc
                out[r][c] = 4
    return out
