def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=max({v for row in grid for v in row},key=lambda v:sum(row.count(v) for row in grid))
    dots=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg and r not in (0,h-1) and c not in (0,w-1)]
    # Rays from each dot extend toward the closest non-background object in each
    # cardinal direction; encountered dot is marked 4. This reproduces the cases
    # where an object sends rays along an otherwise uniform field.
    for r,c in dots:
        v=grid[r][c]
        for dr,dc in ((0,-1),(0,1),(-1,0),(1,0)):
            i,j=r+dr,c+dc
            while 0<=i<h and 0<=j<w and grid[i][j]==bg:
                out[i][j]=v; i+=dr; j+=dc
        out[r][c]=4
    # On boundary lines, non-background segment cells act as continuous emitters
    # along the inward normal, filling the adjacent band with their color.
    for r in range(h):
        if grid[r][0]!=bg and r not in (0,h-1):
            for c in range(1,w-1):
                if grid[r][c]==bg:out[r][c]=grid[r][0]
        if grid[r][-1]!=bg and r not in (0,h-1):
            for c in range(1,w-1):
                if grid[r][c]==bg:out[r][c]=grid[r][-1]
    return out
